INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6613316656835185486a','Renal &Urology amedex 2025.pdf','26','Renal/Urology','A 70-year-old woman with chronic renal failure on peritoneal dialysis presents with two hours of generalized abdominal pain, fever, and rebound tenderness. Which one of the following is the most appropriate next step in management?','{"A":"Erect and supine abdominal films.","B":"Ultrasonography of the abdomen.","C":"CT scan of the abdomen and pelvis.","D":"Peritoneal fluid analysis and Gram stain.","E":"Compare ascitic fluid amylase with serum amylase."}','D',NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Renal &Urology amedex 2025.pdf","supporting_pages":[26],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch025-2026-09-24","parser_mode":"manual_visual_review_batch025","text_method":"manual_visual_transcription","visual_asset":"manual_review_assets/Renal_Urology_amedex_2025__e6b19852fb20/page_00026.jpg","asset_preview_url":"https://drive.google.com/file/d/1fiDqkLKD4IWzdBKda2yUbWiAoYfqrEsS/preview"}','manual_review_assets/Renal_Urology_amedex_2025__e6b19852fb20/page_00026.jpg','https://drive.google.com/thumbnail?id=1fiDqkLKD4IWzdBKda2yUbWiAoYfqrEsS&sz=w1600','text',NULL,'needs_verification','[]','medium','{"batch":"025","source_key":"Renal_Urology_amedex_2025__e6b19852fb20","source_file":"Renal &Urology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Renal &Urology amedex 2025.pdf","page":26,"stem":"A 70-year-old woman with chronic renal failure on peritoneal dialysis presents with two hours of generalized abdominal pain, fever, and rebound tenderness. Which one of the following is the most a