risk":"medium","currentness_keywords":["age","duration"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b5dca29e2ee5fd52b8a03edca6969d5370256ae3","duplicate_group_id":"exact-b5dca29e2ee5","duplicate_sources":[{"record_id":"4f4da6a6bfa04d9a3dd8","record_type":"text_mcq","source_file":"Renal &Urology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Renal &Urology amedex 2025.pdf","source_page":43,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
