INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f6876612f38dee9f119a','Respiratory and chest amedex 2025.pdf','1','Respiratory','A 12-year-old boy is brought to the emergency department with a progressively worsening
asthma attack. He has past medical history of previous asthma attacks and recurrent chest
infections. Which one of the following, if present, would indicate life-threatening asthma?','{"A":"A. Wheeze.","B":"OB. Cyanosis.","C":"C. Speaking in sentences.","D":"D. Peak expiratory flow more than 75%.","E":"E. Oxygen saturation 95%."}','B','If present, cyanosis indicates a life-threatening asthma episode. Other indicators of severity are
FEV1<50%, peak expiratory flow <50%, the patient speaking in words, physical exhaustion, pulse
rate>120bpm, oxygen saturation<92%, and significant accessory muscles use.

(Option A) Wheeze is not a reliable indicator of the severity of an asthma attack. In a severe
attack, the wheeze disappears and results in the ''silent chest'' just prior to respiratory collpase. A
loud wheeze may not be heard in the noisy environmet of the emergency department.

(Option C) A patient can speak in sentences in mild attack, in phrases in moderate and in words
in severe attacks.

(Option D) Peak expiratory flow meter is usually more than 75% in mild asthma, 50-75% in
moderated and <50% is severe asthma attacks.

(Option E) Oxygen saturation of more than 94% is seen in mild, between 92-94% in moderate
and <92% in a severe attacks.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[1],"source_qid":null,"duplicate_group_id":"exact-645ecd257ef2","duplicate_sources":[{"record_id":"f6876612f38dee9f119a","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":1,"source_qid":null},{"record_id":"da30bb4fb87c4068d6f8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1768,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"f6876612f38dee9f119a","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":1,"supporting_pages":[1],"source_qid":null,"domain_hint":"Respiratory","stem":"A 12-year-old boy is brought to the emergency department with a progressively worsening\nasthma attack. He has past medical history of previous asthma attacks and recurrent chest\ninfections. Which one of the following, if present, would indicate life-threatening asthma?","options":{"A":"A. Wheeze.","B":"OB. Cyanosis.","C":"C. Speaking in sentences.","D":"D. Peak expiratory flow more than 75%.","E":"E. Oxygen saturation 95%."},"source_answer":"B","source_explanation":"If present, cyanosis indicates a life-threatening asthma episode. Other indicators of severity are\nFEV1<50%, peak expiratory flow <50%, the patient speaking in words, physical exhaustion, pulse\nrate>120bpm, oxygen saturation<92%, and significant accessory muscles use.\n\n(Option A) Wheeze is not a reliable indicator of the severity of an asthma attack. In a severe\nattack, the wheeze disappears and results in the ''silent chest'' just prior to respiratory collpase. A\nloud wheeze may not be heard in the noisy environmet of the emergency department.\n\n(Option C) A patient can speak in sentences in mild attack, in phrases in moderate and in words\nin severe attacks.\n\n(Option D) Peak expiratory flow meter is usually more than 75% in mild asthma, 50-75% in\nmoderated and <50% is severe asthma attacks.\n\n(Option E) Oxygen saturation of more than 94% is seen in mild, between 92-94% in moderate\nand <92% in a severe attacks.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["asthma"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"645ecd257ef22b8bac33449565a432d75b28dc10","duplicate_group_id":"exact-645ecd257ef2","duplicate_sources":[{"record_id":"f6876612f38dee9f119a","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":1,"source_qid":null},{"record_id":"da30bb4fb87c4068d6f8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1768,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,v