INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('977ca485d32bd6680ec0','Respiratory and chest amedex 2025.pdf','6','Respiratory','A 5-year-old boy is brought to your practice, by his mother, because of intermittent attacks of wheezing,
which have beein occurring 4-6 times a year over the past 2 years. These attacks are usually
precipitated by viral upper respiratory tract infections and last 2-3 days. The symptoms respond to
treatment with inhaled salbutamol. There are no interval symptoms. His older brother had flexural
eczema until the age of 18 months. Which one of the following is the most appropriate management of
this child?','{"A":"Inhaled sodium cromoglycate.","B":"Inhaled fluticanose.","C":"Oral montelukast.","D":"Oral prednisolone when symptomatic.","E":"OE. Inhaled salbutamol when symptomatic."}','E','With infrequent episodes of wheezing and absence of interval symptoms, this child is most likely to have
mild intermittent asthma. Mild asthma in children and adults is managed by short-acting B2 agonists
such as salbutamol.

Inhaled fluticasone or other corticosteroids are not used for mild intermittent asthma, and is reserved for
more severe forms of asthma. Montelukast is often considered and tried for a period of 2-4 weeks before
the child is started on inhaled corticosteroids in an attempt to spare the child from corticosteroids and
their potential adverse effects.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-aa73b4efa128","duplicate_sources":[{"record_id":"977ca485d32bd6680ec0","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":6,"source_qid":null},{"record_id":"0c4fef992eddb98e67eb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1769,"source_qid":"380"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"977ca485d32bd6680ec0","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":6,"source_qid":null,"domain_hint":"Respiratory","stem":"A 5-year-old boy is brought to your practice, by his mother, because of intermittent attacks of wheezing,\nwhich have beein occurring 4-6 times a year over the past 2 years. These attacks are usually\nprecipitated by viral upper respiratory tract infections and last 2-3 days. The symptoms respond to\ntreatment with inhaled salbutamol. There are no interval symptoms. His older brother had flexural\neczema until the age of 18 months. Which one of the following is the most appropriate management of\nthis child?","options":{"A":"Inhaled sodium cromoglycate.","B":"Inhaled fluticanose.","C":"Oral montelukast.","D":"Oral prednisolone when symptomatic.","E":"OE. Inhaled salbutamol when symptomatic."},"source_answer":"E","source_explanation":"With infrequent episodes of wheezing and absence of