INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('de0419e4c46fc5908aac','Respiratory and chest amedex 2025.pdf','8','Respiratory','Ashley is brought to your clinic by his mother. He is a 9-year-old boy who was diagnosed with
intermittent asthma two years ago. He is on inhaled salbutamol as needed. His mother mentions
that he has had to use his medication more frequently recently. Moreover, he has developed
night coughs at least 2 to 3 times weekly. Examination reveals diffuse wheezing over the lung
fields. You explain to her that Asley needs more medications to control his symptoms. You offer
inhaled corticosteroids but she is concerned about the adverse effects of steroids. Which of the
following would be the most appropriate next step in management?','{"A":"A. Start him on inhaled fluticasone and salmeterol.","B":"B. Start him on inhaled fluticasone.","C":"C. Start him on a 14-day course of oral steroids.","D":"OD. Start him on Montelukast.","E":"E. Start him on sodium cromoglycate."}','D','This child had been diagnosed with mild intermittent asthma and started on a short-acting B2
agonist (salbutamol) on an as-needed basis, but his asthma is poorly controlled. Once
adherence to therapy and inappropriate medication use are excluded as the possible causes of
unresponsiveness to treatment, the next step would be a 2- to 4-week course of montelukast. If
the symptoms improve, montelukast should be continued; otherwise, it should be replaced with
the lowest effective dose of inhaled corticosteroids as the most appropriate next step in
management. Montelukast is used to spare the child from inhaled corticosteroids and their
potential adverse effects if there is a response.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[8],"source_qid":null,"duplicate_group_id":"exact-2f6ee6a22df5","duplicate_sources":[{"record_id":"de0419e4c46fc5908aac","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":8,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"de0419e4c46fc5908aac","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":8,"supporting_pages":[8],"source_qid":null,"domain_hint":"Respiratory","stem":"Ashley is brought to your clinic by his mother. He is a 9-year-old boy who was diagnosed with\nintermittent asthma two years ago. He is on inhaled salbutamol as needed. His mother mentions\nthat he has had to use his medication more frequently recently. Moreover, he has developed\nnight coughs at least 2 to 3 times weekly. Examination reveals diffuse wheezing over the lung\nfields. You explain to her that Asley needs more medications to control his symptoms. You offer\ninhaled corticosteroids but she is concerned about the adverse effects of steroids. Which of the\nfollowing would be the most appropriate next step in management?","options":{"A":"A. Start him on inhaled fluticasone and salmeterol.","B":"B. Start him on inhaled fluticasone.","C":"C. Start him on a 14-day course of oral steroids.","D":"OD. Start him on Montelukast.","E":"E. Start him on sodium cromoglycate."},"source_answer":"D","source_explanation":"This child had been 