INSERT INTO question_options (id,question_id,option_key,text_en,text_zh,sort_order) VALUES ('e3b0877b7eef04623f9e-D','e3b0877b7eef04623f9e','D','(Option D) Hydatid cysts are caused by parasitic infection (Echinococcus) and typically present as well-defined,
round cystic lesions on X-ray, often located in the lower lobes. While weight loss can occur with hydatid disease, it
is not a prominent and common feature.',NULL,4);
