INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d97274f6987cf8ab91ed','Respiratory and chest amedex 2025.pdf','27','Respiratory','A 25-year-old woman presents to the emergency department with exacerbation of asthma. Which one of
the following is the most accurate tool to assess the severity of the attack?','{"A":"A. Oxygen pressure of arterial blood (PaO2).","B":"B. Loudness of the wheeze.","C":"C. Severity of the dyspnoea.","D":"OD. Forced expiratory volume in one second (FEV1).","E":"E. Pulse rate."}','D','Oxygen pressure of arterial blood (PaO2) is reduced in severe asthma as a result of ventilation/perfusion
mismatch, but it must be interpreted in relation to the concentration of inhaled oxygen to in order to
determine the arterial-alveolar (a-A) oxygen gradient.

Wheezing and its loudness is not a reliable indicator. In sever disease, the wheezing may decrease
significantly, resulting in ‘silent-chest’ that is an ominous sign. The wheezing is minimal both with mild
attack and just prior to respiratory arrest in very severe attacks.

In an asthma attack, the severity of the dyspnea is usually a marker of the disease severity, but not the
best one because it may be affected by physiologic conditions such as anxiety.

Forced expiratory volume in one second (FEV1), or peak expiratory flow rate (PEFR) is the best guide to
assess the severity, as well as the response to treatment. Of these two, FEV1 is the best single indicator.

Pulse rate is usually increased in an asthma attack but it might be a consequence of anxiety or the effect
of beta 2 agonist or atropine —like drugs such as ipratropium bromide.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[27],"source_qid":null,"duplicate_group_id":"exact-62e507913803","duplicate_sources":[{"record_id":"d97274f6987cf8ab91ed","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":27,"source_qid":null},{"record_id":"9c900b702bfcbf8b0261","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1762,"source_qid":"375"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d97274f6987cf8ab91ed","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":27,"supporting_pages":[27],"source_qid":null,"domain_hint":"Respiratory","stem":"A 25-year-old woman presents to the emergency department with exacerbation of asthma. Which one of\nthe following is the most accurate tool to assess the severity of the attack?","options":{"A":"A. Oxygen pressure of arterial blood (PaO2).","B":"B. Loudness of the wheeze.","C":"C. Severity of the dyspnoea.","D":"OD. Forced expiratory volume in one second (FEV1).","E":"E. Pulse rate."},"source_answer":"D","source_explanation":"Oxygen pressure of arterial blood (PaO2) is reduced in severe asthma as a result of ventilation/perfusion\nmismatch, but it must be interpreted in relation to the concentration of inhaled oxygen to in order to\ndetermine the arterial-alveolar (a-A) oxygen gradient.\n\nWheezing and its loudness is not a reliable indicator. In sever disease, the wheezing may decrease\nsignificantly, resulting in ‘silent-chest’ that is an ominous sign. The wheezing is minimal both with mild\nattack and just prior to respiratory arrest in very severe attacks.\n\nIn an asthma attack, the severity of the dyspnea is usually a marker of the disease severity, but not the\nbest one because it may be affected by physiologic conditions such as anxiety.\n\nForced expiratory volume in one second (FEV1), or peak expiratory flow rate (PEFR) is the best guide to\nassess the severity, as well as the response to treatment. Of these two, FEV1 is the best single indicator.\n\nPulse rate is usually increased in an asthma attack but it might be a consequence of anxiety or the effect\nof beta 2 agonist or atropine —like drugs such as ipratropium bromide.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["asthma","drug","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"62e507913803d5056637ee1241dbd8ba3fd50638","duplicate_group_id":"exact-62e507913803","duplicate_sources":[{"record_id":"d97274f6987cf8ab91ed","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":27,"source_qid":null},{"record_id":"9c900b702bfcbf8b0261","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1762,"source_qid":"375"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,s