INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9fc0faf7a3f6eabfe563','Respiratory and chest amedex 2025.pdf','31','Respiratory','Size of pneumothorax - Accurate estimation of the size of a pneumothorax is difficult. There are different methods for estimation:
e The average interintrapleuralance (AID) method - approximates the size of pneumothorax from a PA CXR in stands ing position by taking the sum of
the distances (measured in millimeters) between the ribs and the visceral pleura at the apical level (A), midthoracic (B), and basal level (C), then
dividing the sum by 3.
e Light Index — An upright PA chest X-ray is obtained. The width of the lung and the hemithorax are measured (in centimeters). The percentage of
pneumothorax is calculated from the following formula:
Pneumothorax percentage = (1 — (width of the lung)*/(width of the hemithorax)3)x1 00
For example, if the width of the lung and the hemithorax are 5 cm and 10 cm respectively, the percentage of pneumothorax will be:
1- (5)3 /( 10)?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[31],"source_qid":null,"duplicate_group_id":"exact-aba308f53396","duplicate_sources":[{"record_id":"9fc0faf7a3f6eabfe563","record_type":"visual_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":31,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Respiratory_and_chest_amedex_2025__c48cb7d3e5ae/page_00031.jpg","asset_preview_url":"https://drive.google.com/file/d/191xW3prej1WnmztYKKLbZTvQzL6XcCg8/preview"}','visual_assets/Respiratory_and_chest_amedex_2025__c48cb7d3e5ae/page_00031.jpg','https://drive.google.com/thumbnail?id=191xW3prej1WnmztYKKLbZTvQzL6XcCg8&sz=w1600','source_page_image',NULL,'needs_verification','[]','medium','{"record_id":"9fc0faf7a3f6eabfe563","record_type":"visual_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":31,"supporting_pages":[31],"source_qid":null,"domain_hint":"Respiratory","stem":"Size of pneumothorax - Accurate estimation of the size of a pneumothorax is difficult. There are different methods for estimation:\ne The average interintrapleuralance (AID) method - approximates the size of pneumothorax from a PA CXR in stands ing position by taking the sum of\nthe distances (measured in millimeters) between the ribs and the visceral pleura at the apical level (A), midthoracic (B), and basal level (C), then\ndividing the sum by 3.\ne Light Index — An upright PA chest X-ray is obtained. The width of the lung and the hemithorax are measured (in centimeters). The percentage of\npneumothorax is calculated from the following formula:\nPneumothorax percentage = (1 — (width of the lung)*/(width of the hemithorax)3)x1 00\nFor example, if the width of the lung and the hemithorax are 5 cm and 10 cm respectively, the percentage of pneumothorax will be:\n1- (5)3 /( 10)?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Respiratory_and_chest_amedex_2025__c48cb7d3e5ae/page_00031.jpg","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"aba308f53396f9a451bdab445c0674ac737f6fcc","duplicate_group_id":"exact-aba308f53396","duplicate_sources":[{"record_id":"9fc0faf7a3f6eabfe563","record_type":"visual_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":31,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_v