INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('81664af1d503ff559567','Respiratory and chest amedex 2025.pdf','40','Respiratory','A 6-month-old child, with confirmed diagnosis of asthma, is given 6 puffs of salbutamol during an acute asthma
attack without adequate response. Which one of the following would be the next best step in management?','{"A":"OA. Repeat another 6 puffs of salbutamol.","B":"B. Give 4 puffs of ipratropium bromide.","C":"C. Give oral steroids.","D":"D. Give intravenous steroids.","E":"E. Give inhaled steroids."}','A','Asthma is less common in children younger than 12 months of age. However, if contracted at this age, it is poorly
responsive to bronchodilators.

Oxygen and short-acting beta-2 agonists such as salbutamol are used routinely despite poor response to B2
agonists, because a mild asthma attack can still be managed by salbutamol.

Initially up to 6 puffs for children ages 0-5 years and up to 12 puffs for those 6 years or older are given. 20
minutes is waited and the respond assessed. If the attack does not subside, up to 6 puffs can be given every 20
minutes for one hour. If these measures failed ipratropium bromide would be added (4 puffs by mask and spacer
or 250 mcg by nebuliser for children 0-5 years, or 8 puffs by mask and spacer or 500 mcg by nebuliser for
children older than 6 years.

The role of ipratropium in management of an acute asthma attack is controversial. It should be considered if the
asthma is severe and unresponsive to maximum dose of short-acting beta agonists.

Oral prednisolone 1 mg/kg should also be given for the first 3 days after the asthma attack.

Corticosteroids have minimal role in acute management of asthma, but should be considered to prevent relapses.
Oral forms of steroids (Suspension) are available in Australia.

Once the acute attack subsides, the child should be reviewed daily for revision of management plan.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[40],"source_qid":null,"duplicate_group_id":"exact-1db99a8c1ae3","duplicate_sources":[{"record_id":"81664af1d503ff559567","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":40,"source_qid":null},{"record_id":"4ba7a007c2790e0c2d28","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1765,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"81664af1d503ff559567","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":40,"supporting_pages":[40],"source_qid":null,"domain_hint":"Respiratory","stem":"A 6-month-old child, with confirmed diagnosis of asthma, is given 6 puffs of salbutamol during an acute asthma\nattack without adequate response. Which one of the following would be the next best step in management?","options":{"A":"OA. Repeat another 6 puffs of salbutamol.","B":"B. Give 4 puffs of ipratropium bromide.","C":"C. Give oral steroids.","D":"D. Give intravenous steroids.","E":"E. Give inhaled steroids."},"source_answer":"A","source_explanation":"Asthma is less common in children younger than 12 months of age. However, if contracted at this age, it is poorly\nresponsive to bronchodilators.\n\nOxygen and short-acting beta-2 agonists such as salbutamol are used routinely despite poor response to B2\nagonists, because a mild asthma attack can still be managed by salbutamol.\n\nInitially up to 6 puffs for children ages 0-5 years and up to 12 puffs for those 6 years or older are given. 20\nminutes is waited and the respond assessed. If the attack does not subside, up to 6 puffs can be given every 20\nminutes for one hour. If these measures failed ipratropium bromide would be added (4 puffs by mask and spacer\nor 250 mcg by nebuliser for children 0-5 years, or 8 puffs by mask and spacer or 500 mcg by nebuliser for\nchildren older than 6 years.\n\nThe role of ipratropium in management of an acute asthma attack is controversial. It should be considered if the\nasthma is severe and unresponsive to maximum dose of short-acting beta agonists.\n\nOral prednisolone 1 mg/kg should also be given for the first 3 days after the asthma attack.\n\nCorticosteroids have minimal role in acute management of asthma, but should be considered to prevent relapses.\nOral forms of steroids (Suspension) are available in Australia.\n\nOnce the acute attack subsides, the child should be reviewed daily for revision of management plan.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","dose","management"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1db99a8c1ae37cec607c718a8f6f052bcc06de92","duplicate_group_id":"exact-1db99a8c1ae3","duplicate_sources":[{"record_id":"81664af1d503ff559567","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":40,"source_qid":null},{"record_id":"4ba7a007c2790e0c2d28","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1765,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
