INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ee40b80ff629eb207768','Respiratory and chest amedex 2025.pdf','41','Respiratory','Which one of the following is never indicated in acute management of an asthma attack in children?','{"A":"A. Steroids.","B":"B. Salbutamol.","C":"C. Ipratropium bromide.","D":"OD. Sodium cromoglycate.","E":"E. Adrenaline."}','D','Sodium cromoglycate is indicated in the prophylactic treatment of asthma, including prevention of
exercise-induced bronchospasm. It is not useful in management of an acute asthma attack.

The management of acute asthma depends on the severity of the symptoms:

Salbutamol (short-acting B2 agonist) is the best initial treatment in all cases of acute asthma.
Systemic steroids are useful in moderate to severe attacks adn should be continued for 3 days and
stopped without tapering.

Ipratropium bromide (an anticholinergic agent) can also be helpful in management of moderate to
severe asthma attack if maximum dose of short-acting B2 agonists fail to break the attack.
Adrenaline can be used in severe asthma attack where there is imminent cardiorespiratory arrest or
when there is anaphylactic reaction.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[41],"source_qid":null,"duplicate_group_id":"exact-55557b02e435","duplicate_sources":[{"record_id":"ee40b80ff629eb207768","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":41,"source_qid":null},{"record_id":"4a907c0c980879783829","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1757,"source_qid":"370"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"ee40b80ff629eb207768","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":41,"supporting_pages":[41],"source_qid":null,"domain_hint":"Respiratory","stem":"Which one of the following is never indicated in acute management of an asthma attack in children?","options":{"A":"A. Steroids.","B":"B. Salbutamol.","C":"C. Ipratropium bromide.","D":"OD. Sodium cromoglycate.","E":"E. Adrenaline."},"source_answer":"D","source_explanation":"Sodium cromoglycate is indicated in the prophylactic treatment of asthma, including prevention of\nexercise-induced bronchospasm. It is not useful in management of an acute asthma attack.\n\nThe management of acute asthma depends on the severity of the symptoms:\n\nSalbutamol (short-acting B2 agonist) is the best initial treatment in all cases of acute asthma.\nSystemic steroids are useful in moderate to severe attacks adn should be continued for 3 days and\nstopped without tapering.\n\nIpratropium bromide (an anticholinergic agent) can also be helpful in management of moderate to\nsevere asthma attack if maximum dose of short-acting B2 agonists fail to break the attack.\nAdrenaline can be used in severe asthma attack where there is imminent cardiorespiratory arrest or\nwhen there is anaphylactic reaction.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","dose","management","prophyl","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"55557b02e4354e4dc4071f23f6e2b86dc04854a7","duplicate_group_id":"exact-55557b02e435","duplicate_sources":[{"record_id":"ee40b80ff629eb207768","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":41,"source_qid":null},{"record_id":"4a907c0c980879783829","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1757,"source_qid":"370"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record