INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d5273fcf0d9e3beff165','Respiratory and chest amedex 2025.pdf','46','Respiratory','A mother brings her 3-year-old boy to your practice with episodic asthma and persistent interval
symptoms of nocturnal cough and exercise-induced wheezing. You plan to start her on
fluticasone. Which one of the following delivery methods is most appropriate for this age group?','{"A":"A. Oral suspension.","B":"B. Metered dose inhaler (MDI).","C":"OC. MDI and spacer device with mask.","D":"D. Nebulizer and pump.","E":"E. Breath-actuated inhaler (Accuhaler®)."}','C','(Option A) Fluticasone is not available in form oral suspension or solution. Moreover, systemic
use of corticosteroids unnecessarily poses the child at adverse effects assoiciated with systemic
corticosteroids.

(Option B) Metered dose inhalers are not an effective delivery mode in this age group, as it
needs breath-holding.

(Option C) MDI and spacer device with mask is the preferred mode of delivery for inhalers in
young children unable to efficiently hold their breath.

(Option D) Nebulizers are also effective but are more expensive and difficult to use compared
with spacers with face mask. They should be considered if the patient cannot cope with spacer
and face mask. They are the second best option.

(Option E) Breath-actuated inhalers are inhalers that automatically release a spray of medication
when the person begins to inhale. Like MDIs this mode of delivery is difficult to use in young
children.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[46],"source_qid":null,"duplicate_group_id":"exact-9f5288d9f49e","duplicate_sources":[{"record_id":"d5273fcf0d9e3beff165","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":46,"source_qid":null},{"record_id":"7c50dcac3f41cc2a6eee","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":10,"source_qid":null},{"record_id":"b7d8899b9bafe6c8ed18","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":9,"source_qid":null},{"record_id":"141238639d83b70c34cd","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1758,"source_qid":"372"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d5273fcf0d9e3beff165","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":46,"supporting_pages":[46],"source_qid":null,"domain_hint":"Respiratory","stem":"A mother brings her 3-year-old boy to your practice with episodic asthma and persistent interval\nsymptoms of nocturnal cough and exercise-induced wheezing. You plan to start her on\nfluticasone. Which one of the following delivery methods is most appropriate for this age group?","options":{"A":"A. Oral suspension.","B":"B. Metered dos