INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('87ea5b8f8b1b3ddcddb5','Respiratory and chest amedex 2025.pdf','52','Respiratory','Which one of the following is unlikely to cause central cyanosis?','{"A":"A. Polycythemia.","B":"B. Right-to-left cardiac shunt.","C":"OC. Left-to-right cardiac shunt.","D":"D. Acute pulmonary edema.","E":"E. Respiratory depression."}','C','All the given options are associated with central cyanosis except left-to-right shunts. With left-to-
right shunts oxygenated blood goes from the left heart to the right heart and no unsaturated blood
enters the systemic circulation to cause cyanosis.

Examples of left-to-right shunt include patent foramen ovale, atrial septal defects, ventricle septal
defects and patent ductus arteriosus.

Right-to-left shunting is seen in transposition of the great vessels, persistent truncus arteriosus
and tetralogy of Fallot.

Polycythemia, decreased respiration and acute pulmonary edema can cause central cyanosis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[52],"source_qid":null,"duplicate_group_id":"exact-80d217efbab6","duplicate_sources":[{"record_id":"87ea5b8f8b1b3ddcddb5","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":52,"source_qid":null},{"record_id":"c3b2362513c8461bb3fb","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":72,"source_qid":null},{"record_id":"0ac21738668ecdaec99b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1805,"source_qid":"522"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"87ea5b8f8b1b3ddcddb5","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":52,"supporting_pages":[52],"source_qid":null,"domain_hint":"Respiratory","stem":"Which one of the following is unlikely to cause central cyanosis?","options":{"A":"A. Polycythemia.","B":"B. Right-to-left cardiac shunt.","C":"OC. Left-to-right cardiac shunt.","D":"D. Acute pulmonary edema.","E":"E. Respiratory depression."},"source_answer":"C","source_explanation":"All the given options are associated with central cyanosis except left-to-right shunts. With left-to-\nright shunts oxygenated blood goes from the left heart to the right heart and no unsaturated blood\nenters the systemic circulation to cause cyanosis.\n\nExamples of left-to-right shunt include patent foramen ovale, atrial septal defects, ventricle septal\ndefects and patent ductus arteriosus.\n\nRight-to-left shunting is seen in transposition of the great vessels, persistent truncus arteriosus\nand tetralogy of Fallot.\n\nPolycythemia, decreased respiration and acute pulmonary edema can cause central cyanosis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"80d217efbab617959e7186de2c62654406ab79fc","duplicate_group_id":"exact-80d217efbab6","duplicate_sources":[{"record_id":"87ea5b8f8b1b3ddcddb5","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":52,"source_qid":null},{"record_id":"c3b2362513c8461bb3fb","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":72,"source_qid":null},{"record_id":"0ac21738668ecdaec99b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1805,"source_qid":"522"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_ur