INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f285f8e35da781bfc429','Respiratory and chest amedex 2025.pdf','54','Respiratory','Which one of the following is the most common cause of secondary pulmonary hypertension and cor pulmonale?','{"A":"OA. Emphysema.","B":"B. Bronchiectasis.","C":"C. Pulmonary embolism.","D":"D. Pneumothorax.","E":"E. Foreign body."}','A','Emphysema as a component of chronic obstructive pulmonary disease (COPD) is the most common cause of cor
pulmonale worldwide and in Australia.

Causes of cor pulmonale are as follows:
Acute

¢ Pulmonary embolism
e¢ Exacerbation of chronic cor-pulmonale
e Acute respiratory distress syndrome (ARDS)

Chronic

¢ Chronic obstructive pulmonary disease
e Primary pulmonary hypertension

¢ Uncontrolled Persistent Asthma

¢ Loss of lung tissue following trauma or surgery
e End stage pneumoconiosis

¢ Sarcoidosis

¢ 11-4 vertebral subluxation

e Untreated obstructive sleep apnea

¢ Interstitial lung disease

e Sickle cell anemia

¢ Bronchopulmonary dysplasia (in infants)
e Severe thoracic kyphoscoliosis','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","supporting_pages":[54],"source_qid":null,"duplicate_group_id":"exact-56f7416c0a9d","duplicate_sources":[{"record_id":"f285f8e35da781bfc429","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":54,"source_qid":null},{"record_id":"0ef0cb1f482adeb86a09","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (1).pdf","source_page":69,"source_qid":null},{"record_id":"66aa115eed0198056580","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1787,"source_qid":"400"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f285f8e35da781bfc429","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_year":2025,"source_page":54,"supporting_pages":[54],"source_qid":null,"domain_hint":"Respiratory","stem":"Which one of the following is the most common cause of secondary pulmonary hypertension and cor pulmonale?","options":{"A":"OA. Emphysema.","B":"B. Bronchiectasis.","C":"C. Pulmonary embolism.","D":"D. Pneumothorax.","E":"E. Foreign body."},"source_answer":"A","source_explanation":"Emphysema as a component of chronic obstructive pulmonary disease (COPD) is the most common cause of cor\npulmonale worldwide and in Australia.\n\nCauses of cor pulmonale are as follows:\nAcute\n\n¢ Pulmonary embolism\ne¢ Exacerbation of chronic cor-pulmonale\ne Acute respiratory distress syndrome (ARDS)\n\nChronic\n\n¢ Chronic obstructive pulmonary disease\ne Primary pulmonary hypertension\n\n¢ Uncontrolled Persistent Asthma\n\n¢ Loss of lung tissue following trauma or surgery\ne End stage pneumoconiosis\n\n¢ Sarcoidosis\n\n¢ 11-4 vertebral subluxation\n\ne Untreated obstructive sleep apnea\n\n¢ Interstitial lung disease\n\ne Sickle cell anemia\n\n¢ Bronchopulmonary dysplasia (in infants)\ne Severe thoracic kyphoscoliosis","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","hypertension"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"56f7416c0a9d847726d3d21be836a8f4c9d36cc6","duplicate_group_id":"exact-56f7416c0a9d","duplicate_sources":[{"record_id":"f285f8e35da781bfc429","record_type":"text_mcq","source_file":"Respiratory and chest amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Respiratory and chest amedex 2025.pdf","source_page":54,"source_qid":null},{"record_id":"0ef0cb1f482adeb86a09","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (1).pdf","source_page":69,"source_qid":null},{"record_id":"66aa115eed0198056580","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1787,"source_qid":"400"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,p